    11→    public class PatternApiClient
    12→    {
    13→        private readonly HttpClient _http;
    14→        private readonly RequestLogService _log;
    15→        public string BaseUrl { get; private set; } = "/api/Patterns/";
    16→        public event Action<string>? OnError;
    17→
    18→        public PatternApiClient(HttpClient http, RequestLogService log)
    19→        {
    20→            _http = http;
    21→            _log = log;
    22→        }
    23→
    24→        public void SetBaseUrl(string url)
    25→        {
    26→            BaseUrl = url.EndsWith("/") ? url : url + "/";
    27→        }
    28→
    29→        private async Task<T?> GetAsync<T>(string url, int retries = 2)
    30→        {
    31→            for (int i = 0; i <= retries; i++)
    32→            {
    33→                try
    34→                {
    35→                    var fullUrl = BaseUrl.TrimEnd('/') + "/" + url.TrimStart('/');
    36→                    _log.LogRequest(fullUrl);
    37→                    var resp = await _http.GetAsync(fullUrl);
    38→                    var content = await resp.Content.ReadAsStringAsync();
    39→                    _log.LogResponse(fullUrl, content, resp.IsSuccessStatusCode);
    40→                    if (resp.IsSuccessStatusCode)
    41→                    {
    42→                        if (typeof(T) == typeof(string))
    43→                            return (T)(object)content;
    44→                        return JsonSerializer.Deserialize<T>(content, new JsonSerializerOptions { PropertyNameCaseInsensitive = true });
    45→                    }
    46→                    else
    47→                    {
    48→                        OnError?.Invoke($"API error: {resp.StatusCode} {content}");
    49→                        return default;
    50→                    }
    51→                }
    52→                catch (Exception ex)
    53→                {
    54→                    if (i == retries)
    55→                    {
    56→                        OnError?.Invoke($"Network/API error: {ex.Message}");
    57→                        return default;
    58→                    }
    59→                    await Task.Delay(500);
    60→                }
    61→            }
    62→            return default;
    63→        }
